INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13437$nota-0209$m13437$, $m13438$VO2 Max Essentials_Final.pdf$m13438$, $m13439$20$m13439$, $m13440$approximately 50% of people do not demonstrate a plateau when pushed to maximal effort. However, the absence of a plateau doesn't necessarily indicate a failure to reach the true VO2 max, and other criteria such as respiratory exchange ratio above 1.15 (indicating that nearly 100% of energy is being derived from carbohydrate or anaerobic pathways) and blood lactate levels are recommended to verify maximal effort, as well as someone's rating of perceived exertion (which should be maximal at the end of the test if done properly).$m13440$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13441$nota-0218$m13441$, $m13442$VO2 Max Essentials_Final.pdf$m13442$, $m13443$40$m13443$, $m13444$Target heart rate = (Maximal HR [220 – age in years] – resting heart rate)... Start pedaling at an intensity (Wattage) that will produce your target heart rate at a cadence of 50–80 rpm... men start at 150 W and women start at 100 W... reach a steady-state heart rate close to your target within the first two minutes... continue cycling for an additional 4 minutes (6 minutes total).$m13444$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13445$nota-0218$m13445$, $m13446$VO2 Max Essentials_Final.pdf$m13446$, $m13447$41$m13447$, $m13448$Women: VO2 max (L/min) = (0.00193 x workload + 0.326) / (0.769 x steady-state heart rate - 56.1) x 100. Men: VO2 max (L/min) = (0.00212 x workload + 0.299) / (0.769 x steady-state heart rate - 48.5) x 100. In this equation, workload needs to be in kg-m/min. Multiply your workload in Watts by 6.12 to get your workload in kg-m/min. Based on your age, multiply your VO2 max by the correction factor below.$m13448$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13449$nota-0218$m13449$, $m13450$nota-0245$m13450$, $m13451$contraste$m13451$, $m13452$nota-0245/skill-gerais-zonas-fc recomenda evitar a fórmula clássica de FCmáx (220−idade) em favor de Gellish para cálculo de zonas de treino; esta nota usa 220−idade deliberadamente, citado literalmente do protocolo-fonte do teste de Astrand, com finalidade diferente (calibrar a carga do teste, não definir zona de treino) — ver ressalva no corpo$m13452$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13453$nota-0219$m13453$, $m13454$VO2 Max Essentials_Final.pdf$m13454$, $m13455$40$m13455$, $m13456$VO2 max = (distance covered (in meters) – 504.9) / 44.73 [Cooper 12-minute run test]. VO2 max = 75.056 – (3.879 x mile time (in minutes)) [1-mile run]. 76.775 – (2.543 x 1.5 mile time (in minutes)) [1.5-mile run].$m13456$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13457$nota-0234$m13457$, $m13458$Exercise Physiology McArdle.pdf$m13458$, $m13459$238$m13459$, $m13460$Only an 8-mL difference in VO2max occurred between the continuous and discontinuous bicycle tests, but VO2max during cycling averaged 6.4 to 11.2% below treadmill values. The largest difference among the three treadmill running tests equaled only 1.2%.$m13460$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13461$nota-0234$m13461$, $m13462$Exercise Physiology McArdle.pdf$m13462$, $m13463$239$m13463$, $m13464$When competitive cyclists pedal at the rapid frequencies of competition, they too achieve VO2max values equivalent to treadmill VO2max scores.$m13464$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13465$nota-0234$m13465$, $m13466$nota-0161$m13466$, $m13467$complementa$m13467$, $m13468$qualifica a medição de VO2 absoluto/relativo (nota-0161) com o efeito de modalidade de teste: o mesmo indivíduo obtém valores de VO2max diferentes dependendo se o teste é feito em esteira ou cicloergômetro$m13468$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13469$nota-0235$m13469$, $m13470$Exercise Physiology McArdle.pdf$m13470$, $m13471$234$m13471$, $m13472$The Wingate cycle ergometer test represents the most popular test to assess anaerobic capacity... After warming up (3 to 5 min), the subject begins pedaling as fast as possible, without resistance. Within 3 s, a fixed resistance is applied to the flywheel; the subject continues to pedal 'all out' for 30 s... Flywheel resistance equals 0.075 kilogram per kg body mass... Resistance often increases to 0.10 kg per kilogram body mass or higher (up to 0.12 kg) when testing power- and sprint-type athletes.$m13472$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13473$nota-0235$m13473$, $m13474$Exercise Physiology McArdle.pdf$m13474$, $m13475$234$m13475$, $m13476$A male weighing 73.3 kg performs the Wingate test... PP = Force × Distance ÷ Time = (5.5 kp × 9.8 m·s−2) × (12 rev × 6 m/rev) ÷ 5 s = 776.8 W. RPP = PP ÷ Body mass = 776.8 W ÷ 73.3 kg = 10.6 W·kg−1. AF = (Highest PP − Lowest PP) ÷ Highest PP × 100 = (776.8 W − 323.7 W) ÷ 776.8 W × 100 = 58.3%. AW = Force × Total Distance (in 30 s) = 15,523 joules, or 15.5 kJ.$m13476$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13477$nota-0235$m13477$, $m13478$Exercise Physiology McArdle.pdf$m13478$, $m13479$232$m13479$, $m13480$Table 11.2 Wingate Percentile Norms for Average Power and Peak Power for Physically Active Young Adult Men and Women — 50th percentile: Male Avg Power 565 W (7.44 W/kg), Peak Power 689 W (9.22 W/kg); Female Avg Power 381 W (6.39 W/kg), Peak Power 449 W (7.65 W/kg).$m13480$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13481$nota-0235$m13481$, $m13482$nota-0043$m13482$, $m13483$complementa$m13483$, $m13484$o teste de Wingate mede diretamente a capacidade anaeróbia (intensidade supra-VO2max) já descrita conceitualmente na nota-0043, fornecendo um protocolo padronizado e quantitativo para avaliá-la$m13484$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13485$nota-0235$m13485$, $m13486$nota-0154$m13486$, $m13487$pre-requisito$m13487$, $m13488$interpreta a potência pico (sistema fosfagênio) e a fadiga anaeróbia (sistema glicolítico) usando os três sistemas de ressíntese de ATP definidos na nota-0154$m13488$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13489$nota-0245$m13489$, $m13490$Exercise Physiology McArdle.pdf$m13490$, $m13491$479$m13491$, $m13492$Maximum heart rate has commonly been estimated as 220 minus age in years, with values independent of race or gender in children and adults. HR max = 220 − Age (y)$m13492$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13493$nota-0245$m13493$, $m13494$Exercise Physiology McArdle.pdf$m13494$, $m13495$479$m13495$, $m13496$HR max = 206.9 − 0.67 × Age (y)... This prediction equation, with a standard deviation of ±5 to ±8 beats per minute, independent of sex, BMI, and resting heart rate... For example, the above equation can estimate maximum heart rate for a 30-year-old man or woman: HR max = 206.9 − (0.67 × 30) = 187 b·min−1$m13496$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m13497$nota-0245$m13497$, $m13498$Exercise Physiology McArdle.pdf$m13498$, $m13499$480$m13499$, $m13500$Method 2: Karvonen Method (Heart Rate Reserve)... HRmax = 208 − (0.7 × Age, y)... LL THR = (HRmax − HRrest) × 0.50 + HRrest... UL THR = (HRmax − HRrest) × 0.85 + HRrest. Example: Data: Male, age 55 years; HRrest = 60 b·min−1... LLTHR = 115 b·min−1... ULTHR = 154 b·min−1$m13500$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m13501$nota-0245$m13501$, $m13502$nota-0158$m13502$, $m13503$complementa$m13503$, $m13504$fornece as fórmulas de FCmáx prevista e cálculo de zona que complementam a advertência de nota-0158 sobre interpretar FC em contexto$m13504$)
